  "claim": {
    "component_id": "C019.main",
    "value": "When random assignment is infeasible, a comparable contemporaneous cohort should be used and assignment differences documented.",
    "scope": "The fallback comparison design; comparability is a proposed requirement, not an established fact.",
    "provenance": {
      "refs": [
        {
          "source_id": "P010",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P010 directly supplies the fallback design and documentation requirement."
    }
  },
  "signal_basis": {
    "component_id": "C019.signal_basis",
    "value": "Compare first-publication proportions within a predefined observation window using a comparable contemporaneous cohort, documenting assignment differences and checking linkage and capture comparability. Without the stated conditions for causal inference, interpret the difference as an association.",
    "scope": "Proposed fallback comparison after release, assuming execution prerequisites and the described observation; no completed finding or causal effect is asserted.",
